insert into public.activities (slug,title,categories,tagline,description,image_url,image_alt,price,price_from,price_unit,duration,location,highlights,options,badge,featured,position,perk,included,excluded,important,qty_label,gallery) values ('safari-desert-quad-buggy','Désert en quad, moto ou buggy',array['desert']::text[],'100 % adrénaline sur les dunes dorées de Dubaï, au guidon de machines puissantes.','Le désert de Dubaï, c''est un terrain de jeu immense. Choisissez votre monture parmi notre sélection de machines puissantes, puis lancez-vous sur les dunes, toujours encadré par des guides expérimentés.
insert into public.activities (slug,title,categories,tagline,description,image_url,image_alt,price,price_from,price_unit,duration,location,highlights,options,badge,featured,position,perk,included,excluded,important,qty_label,gallery) values ('balade-en-yacht','Yacht privatisé',array['mer']::text[],'Naviguez entre la Marina, Palm Jumeirah et le Burj Al Arab, à bord de votre propre yacht.','Offrez-vous un moment d''exception à bord d''un yacht privatisé, rien que pour vous et vos proches. Cap sur la Marina, la Palm Jumeirah ou le pied du Burj Al Arab, avec un équipage aux petits soins.
insert into public.activities (slug,title,categories,tagline,description,image_url,image_alt,price,price_from,price_unit,duration,location,highlights,options,badge,featured,position,perk,included,excluded,important,qty_label,gallery) values ('montgolfiere-helicoptere','Montgolfière ou hélicoptère',array['ciel']::text[],'Dubaï vue du ciel : les dunes au lever du soleil, ou le skyline en hélicoptère.','Deux façons spectaculaires de vivre Dubaï depuis les airs. Au lever du soleil, la montgolfière glisse en silence au-dessus des dunes dorées : un moment magique et paisible, transfert inclus.
insert into public.activities (slug,title,categories,tagline,description,image_url,image_alt,price,price_from,price_unit,duration,location,highlights,options,badge,featured,position,perk,included,excluded,important,qty_label,gallery) values ('diner-bedouin','Dîner bédouin privatisé',array['desert']::text[],'Une soirée authentique au cœur du désert, avec quad inclus.','Vivez un dîner bédouin privatisé dans un cadre exceptionnel, au cœur du désert. Vous découvrirez un village ensablé, puis partagerez un repas traditionnel sous les étoiles, sans regarder l''heure.
insert into public.activities (slug,title,categories,tagline,description,image_url,image_alt,price,price_from,price_unit,duration,location,highlights,options,badge,featured,position,perk,included,excluded,important,qty_label,gallery) values ('activites-nautiques','Jet-ski, flyboard & plongée',array['mer']::text[],'Jet-ski face au skyline, jet car, flyboard, plongée : choisissez vos sensations.','Profitez d''un large choix d''activités nautiques pour vivre des sensations fortes en pleine mer. Pilotez un jet-ski face aux plus beaux panoramas de la ville, testez le jet car ou décollez au-dessus de l''eau en flyboard.
insert into public.activities (slug,title,categories,tagline,description,image_url,image_alt,price,price_from,price_unit,duration,location,highlights,options,badge,featured,position,perk,included,excluded,important,qty_label,gallery) values ('excursion-oman','Croisière à Oman (Musandam)',array['excursions','mer']::text[],'Les fjords turquoise d’Oman : baignade, snorkeling, repas, et le visa est inclus.','Partez pour une journée inoubliable à Oman, avec le transfert depuis votre hôtel inclus. Vous profiterez d''une croisière de 5 heures entre eaux turquoise et montagnes : baignade, snorkeling, pêche et activités fun comme le bateau banane.
insert into public.activities (slug,title,categories,tagline,description,image_url,image_alt,price,price_from,price_unit,duration,location,highlights,options,badge,featured,position,perk,included,excluded,important,qty_label,gallery) values ('abu-dhabi-tour','Journée à Abu Dhabi',array['excursions','incontournables']::text[],'La Grande Mosquée Sheikh Zayed, Yas Island et la Corniche, avec chauffeur privé.','Découvrez la capitale des Émirats en une journée exceptionnelle. Au programme : la majestueuse Grande Mosquée Sheikh Zayed, Yas Island, le front de mer de la Corniche, et bien plus encore.
insert into public.activities (slug,title,categories,tagline,description,image_url,image_alt,price,price_from,price_unit,duration,location,highlights,options,badge,featured,position,perk,included,excluded,important,qty_label,gallery) values ('burj-khalifa-aquarium','Burj Khalifa + Dubai Aquarium',array['incontournables','famille']::text[],'Entre ciel et océan : la plus haute tour du monde et son aquarium géant.','Une double expérience pour découvrir deux symboles de Dubaï en une seule sortie. Montez au Burj Khalifa, la plus haute tour du monde, et admirez la ville depuis une vue panoramique à couper le souffle.
insert into public.activities (slug,title,categories,tagline,description,image_url,image_alt,price,price_from,price_unit,duration,location,highlights,options,badge,featured,position,perk,included,excluded,important,qty_label,gallery) values ('dolphinarium','Dolphinarium de Dubaï',array['famille']::text[],'Un moment magique au plus près des dauphins, pour petits et grands.','Offrez-vous une rencontre inoubliable avec les dauphins au Dolphinarium de Dubaï. Assistez à leurs démonstrations impressionnantes, ou vivez un moment privilégié à leurs côtés, dans un cadre sécurisé et encadré par des professionnels.
insert into public.activities (slug,title,categories,tagline,description,image_url,image_alt,price,price_from,price_unit,duration,location,highlights,options,badge,featured,position,perk,included,excluded,important,qty_label,gallery) values ('ski-dubai','Ski Dubai',array['famille','incontournables']::text[],'La neige en plein désert : ski, tyrolienne, manèges et rencontre avec les pingouins.','Plongez dans un univers 100 % enneigé en plein désert, avec l''une des attractions les plus insolites de la ville. Snow Park, manèges, tyrolienne, cours de ski et rencontre avec les pingouins : tout dépend de la formule choisie.
insert into public.activities (slug,title,categories,tagline,description,image_url,image_alt,price,price_from,price_unit,duration,location,highlights,options,badge,featured,position,perk,included,excluded,important,qty_label,gallery) values ('refuge-animalier','Refuge animalier',array['famille']::text[],'Rencontrez des animaux sauvés, dans un refuge unique dédié à leur protection.','Vivez une expérience émouvante et éducative dans un refuge animalier de Dubaï, dédié à la protection et au bien-être des animaux. Vous observerez de près différentes espèces, dans un environnement respectueux et sécurisé.
insert into public.activities (slug,title,categories,tagline,description,image_url,image_alt,price,price_from,price_unit,duration,location,highlights,options,badge,featured,position,perk,included,excluded,important,qty_label,gallery) values ('attractions','Parcs & attractions',array['famille','incontournables']::text[],'IMG Worlds, Ferrari World, Global Village, Museum of the Future… vos billets au meilleur prix.','Découvrez les attractions les plus célèbres de Dubaï, avec des expériences pour tous les goûts. Plongez dans l''univers du cinéma et des super-héros à IMG Worlds of Adventure, le plus grand parc indoor au monde, ou vibrez au rythme de la vitesse à Ferrari World.
